const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lutDesertPoint = ee.Geometry.Point([51.81, 30.73]); // A point in the central Lut Desert, Iran
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';
  const scale = 1000; // MODIS LST resolution is 1km

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterDate(startDate, endDate)
    .filterBounds(lutDesertPoint);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No MODIS/061/MOD11A2 images found for Lut Desert in 2018.");
    console.log("C1");
    return;
  }
  console.log(`Initial images found: ${initialSize}`);

  // Function to mask clouds and scale LST
  function maskAndScaleLST(image) {
    // Select the LST_Day_1km band
    const lstDay = image.select('LST_Day_1km');
    // Select the QC_Day band
    const qcDay = image.select('QC_Day');

    // Bits 0-1: LST quality. 00 = Good quality, 01 = Good quality, LST produced with emissivity from classification.
    // Bits 2-3: Cloud persistence (we want clear, 00)
    const lstQuality = qcDay.bitwiseAnd(3); // Extract bits 0-1
    const cloudPersistence = qcDay.rightShift(2).bitwiseAnd(3); // Extract bits 2-3

    // Mask out pixels where LST quality is not good (0 or 1)
    // and where cloud persistence is not clear (0)
    const goodQualityMask = lstQuality.lte(1); // LST Quality 00 or 01
    const clearSkyMask = cloudPersistence.eq(0); // Clear sky

    // Apply masks
    const maskedLST = lstDay.updateMask(goodQualityMask).updateMask(clearSkyMask);

    // Scale LST from Kelvin * 0.02 to Celsius
    // K = LST_raw * 0.02
    // C = K - 273.15
    const lstCelsius = maskedLST.multiply(0.02).subtract(273.15);

    return lstCelsius.rename('LST_Celsius').copyProperties(image, ['system:time_start']);
  }

  // Apply masking and scaling to the collection
  const processedCollection = collection.map(maskAndScaleLST);

  // Find the maximum LST across all images in the collection
  // Use ee.Reducer.max() on the collection directly for temporal max
  const maxLSTImage = processedCollection.reduce(ee.Reducer.max());

  // Check if there's any data after processing
  const pixelCount = await maxLSTImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lutDesertPoint,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid pixels remain after cloud masking for Lut Desert in 2018.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels count after masking: ${pixelCount}`);


  // 4. Calculation
  const maxLST = await maxLSTImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lutDesertPoint,
    scale: scale,
    maxPixels: 1e9
  }).get('LST_Celsius').getInfo();

  // 5. Validation & Final Answer
  if (maxLST === null || isNaN(maxLST)) {
    console.log("Maximum LST calculation failed (result is Null/NaN).");
    console.log("C3");
    return;
  }

  console.log(`Maximum Land Surface Temperature in 2018 for Lut Desert: ${maxLST.toFixed(2)} °C`);

  if (maxLST > 75) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
